def multiplikator(faktor):
    def rechnen(zahl):
        return zahl * faktor
    return rechnen

doppelt = multiplikator(2)
print(doppelt(5))

def dekorator(func):
    def wrapper():
        print("Vorher")
        func()
        print("Nachher")
    return wrapper

@dekorator
def hallo():
    print("Hallo")

hallo()

from functools import wraps

def deco(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper
